let all = [];
let offset = 0;
while (true) {
  const page = search({ limit: 50, offset });
  all = all.concat(page.items.map(i => i.path));
  if (!page.next) break;
  offset = page.next.offset;
}
// Also try explicit namespaces
let nsChecks = [];
for (const ns of ["recon-echo", "recon_echo", "mcpreview", "recon"]) {
  try {
    const r = search({ namespace: ns });
    nsChecks.push({ ns, items: r.items.map(i => i.path) });
  } catch (e) {
    nsChecks.push({ ns, error: String(e) });
  }
}
return { totalFound: all.length, allPaths: all, echoOrRecon: all.filter(p => /echo|recon/i.test(p)), nsChecks };"}

